spec.init:
# Init tab -- runs once per file open (not per compute()).
# Imports + helper functions shared by the Compute expression. Everything
# defined at module level here (the imports AND the functions) is available in
# the Compute tab as a bare name -- so the compute code can call e.g.
# ouch_load_bytes(...) directly.

import os
import hashlib


def ouch_resolve_clip_path(raw):
    """Resolve a requested clip path from the 'audioFile' string. An absolute
    path is used as-is; a relative one resolves against the open scene's
    directory. An empty request resolves to '' (nothing to load) -- the baked
    self.audioData buffer is authoritative, so we never auto-hunt for a file."""
    raw = (raw or "").strip()
    if not raw:
        return ""
    if os.path.isabs(raw):
        return raw
    import maya.cmds as mc
    scene = mc.file(q=True, sceneName=True)
    sdir = os.path.dirname(scene) if scene else ""
    return os.path.join(sdir, raw) if sdir else raw


def ouch_load_bytes(path):
    """Read the whole clip into memory, or None if it can't be read."""
    try:
        with open(path, "rb") as fh:
            return fh.read()
    except Exception:
        return None


def ouch_bytes_signature(data):
    """md5 of the raw audio bytes. This -- NOT the file's path / size / mtime --
    is what gates the player rebuild, so ANY change to self.audioData (a disk
    load OR a manual right-click 'Load media') rebuilds the player and plays the
    new clip. self.audioData is the single source of truth for playback."""
    try:
        return hashlib.md5(bytes(data)).hexdigest()
    except Exception:
        return "baked"


def ouch_audio_ext(data):
    """Pick the temp-file extension that matches the audio bytes so the player's
    backend decodes them. QMediaPlayer keys its decoder off the file suffix, so
    e.g. MP3 bytes MUST land in a .mp3 file, not a .wav. Falls back to .wav."""
    try:
        h = bytes(data)[:12]
    except Exception:
        return ".wav"
    if h[:4] == b"RIFF" and h[8:12] == b"WAVE":
        return ".wav"
    if h[:3] == b"ID3" or (len(h) >= 2 and h[0] == 0xFF and (h[1] & 0xE0) == 0xE0):
        return ".mp3"
    if h[:4] == b"OggS":
        return ".ogg"
    if h[:4] == b"fLaC":
        return ".flac"
    if h[:4] == b"FORM" and h[8:12] in (b"AIFF", b"AIFC"):
        return ".aiff"
    if h[4:8] == b"ftyp" and h[8:11] in (b"M4A", b"M4B", b"M4P"):
        return ".m4a"
    return ".wav"


def ouch_make_player(data, sig):
    """Materialise 'data' to a temp file with the right extension and build Qt's
    async media player. The temp file is named by the content signature so
    distinct clips get distinct files (never a stale one), and MP3/OGG/FLAC bytes
    get a suffix their backend recognises."""
    try:
        import tempfile
        from mpynode.ui.qt_wrapper import make_audio_player
        tmp = os.path.join(
            tempfile.gettempdir(),
            "mpynode_ouch_%s%s" % ((sig or "0")[:12], ouch_audio_ext(data)))
        with open(tmp, "wb") as fh:
            fh.write(bytes(data))
        return make_audio_player(tmp)
    except Exception:
        return None
